begin;
create extension if not exists pgcrypto;
create type user_role as enum ('admin','funcionario');
create type bike_status as enum ('Disponível','Alugada','Avariada','Em manutenção','Indisponível');
create type rental_status as enum ('Em aberto','Concluído');
create type fault_status as enum ('Aberta','Em análise','Em reparação','Resolvida','Cancelada');
create table kiosks(id uuid primary key default gen_random_uuid(),name text not null unique,active boolean not null default true,created_at timestamptz not null default now());
create table users(id uuid primary key default gen_random_uuid(),full_name text not null,username text not null unique check(username=lower(username)),password_hash text not null,role user_role not null default 'funcionario',usual_kiosk_id uuid references kiosks,active boolean not null default true,created_at timestamptz not null default now(),last_login_at timestamptz);
create table sessions(id uuid primary key default gen_random_uuid(),user_id uuid not null references users,token_hash text not null unique,csrf_token text not null,created_at timestamptz not null default now(),expires_at timestamptz not null,revoked_at timestamptz);
create table login_attempts(id bigint generated always as identity primary key,attempt_key text not null,success boolean not null,created_at timestamptz not null default now());
create table bikes(id uuid primary key default gen_random_uuid(),code text not null unique check(code~'^\d+$'),model text not null,photo_url text,kiosk_id uuid not null references kiosks,status bike_status not null default 'Disponível',notes text,active boolean not null default true,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table rentals(id uuid primary key default gen_random_uuid(),reference text not null unique,customer_ref text not null,start_kiosk_id uuid not null references kiosks,status rental_status not null default 'Em aberto',started_at timestamptz not null default now(),started_by uuid not null references users,returned_at timestamptz,returned_by uuid references users,anonymized_at timestamptz,check(char_length(customer_ref)<=200));
create table rental_items(id uuid primary key default gen_random_uuid(),rental_id uuid not null references rentals on delete restrict,bike_id uuid not null references bikes on delete restrict,returned_at timestamptz,returned_by uuid references users,return_kiosk_id uuid references kiosks,anomaly boolean not null default false,anomaly_description text,unique(rental_id,bike_id));
create unique index one_open_rental_per_bike on rental_items(bike_id) where returned_at is null;
create table faults(id uuid primary key default gen_random_uuid(),bike_id uuid not null references bikes on delete restrict,created_at timestamptz not null default now(),created_by uuid not null references users,origin text not null check(origin in('comunicada diretamente','identificada numa devolução')),category text not null,description text not null,severity text not null check(severity in('Baixa','Média','Alta','Impeditiva')),photo_url text,usable boolean not null,status fault_status not null default 'Aberta',notes text);
create table maintenance_interventions(id uuid primary key default gen_random_uuid(),fault_id uuid not null references faults on delete restrict,intervention_date date not null default current_date,description text not null,technician_supplier text,cost numeric(10,2) check(cost>=0),parts_materials text,attachment_url text,created_by uuid not null references users,notes text,created_at timestamptz not null default now());
create table bike_status_history(id bigint generated always as identity primary key,bike_id uuid not null references bikes,status bike_status not null,kiosk_id uuid references kiosks,changed_by uuid references users,note text,created_at timestamptz not null default now());
create table audit_log(id bigint generated always as identity primary key,action text not null,created_at timestamptz not null default now(),user_id uuid references users,entity text not null,entity_id text,old_value jsonb,new_value jsonb,note text);
create index on bikes(status,kiosk_id);create index on rentals(status,started_at desc);create index on faults(status,created_at desc);create index on audit_log(entity,entity_id);create index on login_attempts(attempt_key,created_at desc);
create function touch_updated_at() returns trigger language plpgsql as $$begin new.updated_at=now();return new;end$$;
create trigger bikes_touch before update on bikes for each row execute function touch_updated_at();
alter table kiosks enable row level security;alter table users enable row level security;alter table sessions enable row level security;alter table login_attempts enable row level security;alter table bikes enable row level security;alter table rentals enable row level security;alter table rental_items enable row level security;alter table faults enable row level security;alter table maintenance_interventions enable row level security;alter table bike_status_history enable row level security;alter table audit_log enable row level security;
-- Não são criadas policies: apenas a service role do backend acede às tabelas.
commit;
